const entry = msg.payload;

msg.payload = {
    id:        entry.id,
    text:      entry.text             || "",
    timestamp: entry.timeCreated,
    author:    entry.loggedByFullName || "",
    files:     entry.files            || [],
    labels:    entry.labels           || []
};

return msg;

const entry = msg.payload;

const isLocation = entry.location === true;
let text = entry.content || "";

if (isLocation) {
    try {
        const geojson = JSON.parse(entry.content);
        const [lng, lat] = geojson.geometry.coordinates;
        const description = geojson.properties?.description || "";
        const mapsLink = "Klikk her for å åpne i Google Maps:\nhttps://www.google.com/maps?q=" + lat + "%2C" + lng;
        text = description ? description + "\n\n" + mapsLink : mapsLink;
        msg.geo = { lat, lng };
        msg.isLocation = true;
    } catch (e) {
        text = entry.content || "";
    }
}

msg.payload = {
    id: entry.id,
    text: text,
    timestamp: new Date(entry.createdAt).getTime(),
    author: entry.username || "",
    files: entry.files || [],
    labels: [],
    geo: msg.geo || null,
    isLocation: isLocation
};  

return msg;

if (msg.mapImage) {
    msg.payload.files = (msg.payload.files || []).concat(msg.mapImage);
    delete msg.mapImage;
}

delete msg.geo;
delete msg.isLocation;

return msg;
